"""Shared utilities: token counting, text sanitization, formatting."""

from __future__ import annotations

import json
import os
from functools import lru_cache
from typing import Any

import tiktoken
import tiktoken.load

# ── Tiktoken encoder (loaded from local cache if available) ────
_CACHE_PATH = os.path.expanduser("~/.cache/tiktoken/cl100k_base.tiktoken")
_ENCODER: tiktoken.Encoding | None = None

if os.path.exists(_CACHE_PATH):
    try:
        _ranks = tiktoken.load.load_tiktoken_bpe(_CACHE_PATH)
        _ENCODER = tiktoken.Encoding(
            name="cl100k_base",
            pat_str=(
                r"(?i:[sdmt]|ll|ve|re)|[^\n\pL\pP\p{Nd}\p{Sc}\p{Sk}\p{So}]+"
                r"|\p{Nd}+|\p{Sc}[\p{Nd}]*|\p{Sc}+|\p{Sk}+|\p{So}+"
                r"|\p{Ll}\p{Lo}|\p{L}\p{L}\p{L}*\p{Ll}\p{Lo}"
            ),
            mergeable_ranks=_ranks,
            special_tokens={
                "<|endoftext|>": 100257,
                "<|fim_prefix|>": 100258,
                "<|fim_middle|>": 100259,
                "<|fim_suffix|>": 100260,
                "<|endofprompt|>": 100276,
            },
        )
    except Exception:
        pass


@lru_cache(maxsize=4096)
def count_tokens(text: str) -> int:
    """Approximate token count via cl100k_base; falls back to len/4."""
    if not text:
        return 0
    if _ENCODER is not None:
        return len(_ENCODER.encode(text, disallowed_special=()))
    return max(1, len(text) // 4)


# ── Text helpers ───────────────────────────────────────────────

def to_str(value: Any) -> str:
    """Coerce any value (bytes, dict, list, None) to a plain string."""
    if value is None:
        return ""
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="replace")
    if isinstance(value, (dict, list)):
        return json.dumps(value, ensure_ascii=False)
    return str(value)


_MERMAID_TABLE = str.maketrans({
    # ASCII straight quotes collapse to single quotes so they cannot prematurely close
    # the outer double-quoted label Mermaid wraps the sanitized text in.
    '"': "'",
    ":": "：", "\n": " ", "[": "(", "]": ")",
    ";": ",", "#": "", "<": "＜", ">": "＞", "&": "＆",
    # Curly/smart/fullwidth quotes are NOT caught by the ASCII mapping above; left
    # unescaped they terminate Mermaid's double-quoted label mid-string and surface
    # as "Syntax error in text" in the sequence diagram. Normalize all of them to
    # ASCII single quotes so agent-generated prose (which freely uses "smart quotes")
    # renders safely inside a Mermaid message label.
    "\u201c": "'",  # left double quotation mark "
    "\u201d": "'",  # right double quotation mark "
    "\u201e": "'",  # double low-9 quotation mark „
    "\u201f": "'",  # double high-reversed-9 quotation mark ‟
    "\uff02": "'",  # fullwidth quotation mark ＂
    "\u2018": "'",  # left single quotation mark '
    "\u2019": "'",  # right single quotation mark '
    "\u201a": "'",  # single low-9 quotation mark ‚
    "\u201b": "'",  # single high-reversed-9 quotation mark ‛
})


def sanitize_mermaid(text: str, max_len: int = 50) -> str:
    """Make a string safe for use in a Mermaid diagram label."""
    text = to_str(text).strip().translate(_MERMAID_TABLE)
    return (text[:max_len] + "…") if len(text) > max_len else text


def mermaid_quote(text: Any) -> str:
    """Return a Mermaid-safe double-quoted label."""
    return f'"{sanitize_mermaid(to_str(text))}"'


def format_duration(ms: int | float) -> str:
    """Human-readable duration from milliseconds."""
    if not ms:
        return "—"
    s = ms / 1000
    if s < 60:
        return f"{s:.1f}s"
    m, rem = divmod(int(s), 60)
    return f"{m}m {rem}s"


def decode_bytes(content: bytes) -> str | None:
    """Try common encodings in order; return None if all fail."""
    for enc in ("utf-8", "utf-8-sig", "utf-16", "latin-1"):
        try:
            return content.decode(enc)
        except (UnicodeDecodeError, Exception):
            continue
    return None

"""Parser for Claude Code output files.

Supports two formats automatically:

1. **stream-json** — produced by `claude -p "task" --output-format stream-json`
   Events: system | assistant | user (wraps tool_result) | result

2. **transcript JSONL** — saved automatically to ~/.claude/projects/<hash>/<session>.jsonl
   during every interactive session.
   Events: user | assistant | tool_result (top-level, NOT nested inside user)
   Each line also carries: uuid, parentUuid, timestamp, sessionId, cwd, version

Auto-detection: if ≥ 3 of the first 10 lines contain both "uuid" and "timestamp"
keys → transcript format; otherwise → stream-json format.
"""

from __future__ import annotations

import json
from datetime import datetime, timezone
from typing import Any

import streamlit as st

from trace_viz.models import ParseResult, ResultInfo, SessionInfo, ToolCall, Turn
from trace_viz.utils import count_tokens, to_str


@st.cache_data(show_spinner=False)
def parse(content: bytes) -> ParseResult:
    """Parse Claude Code NDJSON bytes, auto-detecting format."""
    raw_events = _load_ndjson(content)
    if not raw_events:
        return ParseResult.empty("claude_code")

    # ── Format detection ───────────────────────────────────────
    transcript_hits = sum(
        1 for e in raw_events[:10]
        if "uuid" in e and "timestamp" in e
    )
    if transcript_hits >= 3:
        return _parse_transcript(raw_events)
    return _parse_stream_json(raw_events)


# ── Shared NDJSON loader ───────────────────────────────────────

def _load_ndjson(content: bytes) -> list[dict[str, Any]]:
    events: list[dict] = []
    for line in content.decode("utf-8", errors="replace").splitlines():
        line = line.strip()
        if line:
            try:
                events.append(json.loads(line))
            except json.JSONDecodeError:
                pass
    return events


# ══════════════════════════════════════════════════════════════
# FORMAT 1 — stream-json  (produced by -p / --print)
# ══════════════════════════════════════════════════════════════

def _parse_stream_json(raw_events: list[dict]) -> ParseResult:
    session_info = _sj_session_info(raw_events)
    result_info  = _sj_result_info(raw_events)

    tool_map: dict[str, dict] = {}
    turns: list[Turn] = []
    _sj_collect_assistant(raw_events, turns, tool_map)
    _sj_match_tool_results(raw_events, tool_map)
    tool_calls = _sj_flatten_tool_calls(raw_events, tool_map)

    return ParseResult(
        source="claude_code",
        raw_events=raw_events,
        session_info=session_info,
        result_info=result_info,
        turns=turns,
        tool_calls=tool_calls,
        parse_debug={"format": "stream-json"},
    )


def _sj_session_info(events: list[dict]) -> SessionInfo:
    for evt in events:
        if evt.get("type") == "system":
            return SessionInfo(
                model=evt.get("model", ""),
                session_id=evt.get("session_id", ""),
                permission_mode=evt.get("permissionMode", ""),
                tools_available=[
                    (t.get("name", str(t)) if isinstance(t, dict) else str(t))
                    for t in evt.get("tools", [])
                ],
            )
    return SessionInfo()


def _sj_result_info(events: list[dict]) -> ResultInfo:
    for evt in events:
        if evt.get("type") == "result":
            usage = evt.get("usage", {})
            return ResultInfo(
                duration_ms=evt.get("duration_ms", 0) or 0,
                duration_api_ms=evt.get("duration_api_ms", 0) or 0,
                num_turns=evt.get("num_turns", 0) or 0,
                total_cost_usd=evt.get("total_cost_usd") or 0.0,
                is_error=bool(evt.get("is_error", False)),
                result_text=evt.get("result", ""),
                total_input=usage.get("input_tokens", 0) or 0,
                total_output=usage.get("output_tokens", 0) or 0,
                total_cache_creation=usage.get("cache_creation_input_tokens", 0) or 0,
                total_cache_read=usage.get("cache_read_input_tokens", 0) or 0,
            )
    return ResultInfo()


def _sj_collect_assistant(
    events: list[dict],
    turns: list[Turn],
    tool_map: dict[str, dict],
) -> None:
    for evt in events:
        if evt.get("type") != "assistant":
            continue
        msg   = evt.get("message", {})
        usage = msg.get("usage", {})
        turn_no = len(turns) + 1
        text_parts, tool_count = [], 0

        raw_content = msg.get("content", [])
        if isinstance(raw_content, str):
            raw_content = [{"type": "text", "text": raw_content}]
        for block in raw_content:
            if not isinstance(block, dict):
                continue
            if block.get("type") == "text":
                text_parts.append(block.get("text", ""))
            elif block.get("type") == "tool_use":
                tool_count += 1
                tid = block.get("id", "")
                tool_map[tid] = {
                    "id": tid, "name": block.get("name", ""),
                    "input": block.get("input") or {}, "turn_no": turn_no,
                    "call_idx": len(tool_map), "output": None, "is_error": False,
                    "ts_start": None, "ts_end": None,
                }

        turns.append(Turn(
            turn_no=turn_no,
            input_tokens=usage.get("input_tokens", 0) or 0,
            output_tokens=usage.get("output_tokens", 0) or 0,
            cache_read=usage.get("cache_read_input_tokens", 0) or 0,
            cache_creation=usage.get("cache_creation_input_tokens", 0) or 0,
            stop_reason=msg.get("stop_reason", ""),
            text_content="\n".join(text_parts),
            tool_count=tool_count,
            model=msg.get("model", ""),
        ))


def _sj_match_tool_results(
    events: list[dict], tool_map: dict[str, dict]
) -> None:
    for evt in events:
        if evt.get("type") != "user":
            continue
        for block in evt.get("message", {}).get("content", []):
            if block.get("type") != "tool_result":
                continue
            tid = block.get("tool_use_id", "")
            if tid not in tool_map:
                continue
            content = block.get("content", "")
            if isinstance(content, list):
                content = "\n".join(
                    (c.get("text", str(c)) if isinstance(c, dict) else str(c))
                    for c in content
                )
            tool_map[tid]["output"]   = content
            tool_map[tid]["is_error"] = bool(block.get("is_error", False))


def _sj_flatten_tool_calls(
    events: list[dict], tool_map: dict[str, dict]
) -> list[ToolCall]:
    calls, seen = [], set()
    for evt in events:
        if evt.get("type") != "assistant":
            continue
        for block in evt.get("message", {}).get("content", []):
            if block.get("type") != "tool_use":
                continue
            tid = block.get("id", "")
            if tid in seen or tid not in tool_map:
                continue
            seen.add(tid)
            tc   = tool_map[tid]
            text = to_str(tc.get("output") or "")
            calls.append(ToolCall(
                name=tc["name"], input=tc["input"], output=text,
                is_error=tc["is_error"], turn_no=tc["turn_no"],
                call_idx=tc["call_idx"],
                tiktoken_tokens=count_tokens(text),
                output_chars=len(text),
            ))
    return calls


# ══════════════════════════════════════════════════════════════
# FORMAT 2 — transcript JSONL  (~/.claude/projects/*/*.jsonl)
# ══════════════════════════════════════════════════════════════

def _parse_transcript(raw_events: list[dict]) -> ParseResult:
    """Parse the persistent JSONL transcripts saved by interactive sessions."""

    # ── Session metadata from any event ───────────────────────
    session_id = next((e.get("sessionId", "") for e in raw_events if e.get("sessionId")), "")
    cwd        = next((e.get("cwd",       "") for e in raw_events if e.get("cwd")),       "")
    version    = next((e.get("version",   "") for e in raw_events if e.get("version")),   "")

    tool_map: dict[str, dict] = {}   # tool_use id → record
    turns:      list[Turn]     = []
    model = ""

    # ── Pass 1: assistant messages → turns + tool_use entries ─
    for evt in raw_events:
        if evt.get("type") != "assistant":
            continue
        msg = evt.get("message", {})
        if not isinstance(msg, dict):
            continue

        usage    = msg.get("usage", {})
        turn_no  = len(turns) + 1
        if not model:
            model = msg.get("model", "")

        text_parts, tool_count = [], 0
        raw_content = msg.get("content", [])
        # content may be a plain string, a list of dicts, or a list of strings
        if isinstance(raw_content, str):
            raw_content = [{"type": "text", "text": raw_content}]
        for block in raw_content:
            if isinstance(block, str):
                text_parts.append(block)
                continue
            if not isinstance(block, dict):
                continue
            btype = block.get("type", "")
            if btype == "text":
                text_parts.append(block.get("text", ""))
            elif btype == "tool_use":
                tool_count += 1
                tid = block.get("id", "")
                tool_map[tid] = {
                    "id":        tid,
                    "name":      block.get("name", ""),
                    "input":     block.get("input") or {},
                    "turn_no":   turn_no,
                    "call_idx":  len(tool_map),
                    "output":    None,
                    "is_error":  False,
                    # timestamps from the wrapping event
                    "ts_start":  evt.get("timestamp"),
                    "ts_end":    None,
                }

        turns.append(Turn(
            turn_no=turn_no,
            input_tokens=usage.get("input_tokens", 0) or 0,
            output_tokens=usage.get("output_tokens", 0) or 0,
            cache_read=usage.get("cache_read_input_tokens", 0) or 0,
            cache_creation=usage.get("cache_creation_input_tokens", 0) or 0,
            stop_reason=msg.get("stop_reason", ""),
            text_content="\n".join(text_parts),
            tool_count=tool_count,
            model=msg.get("model", ""),
        ))

    # ── Pass 2: tool_result blocks nested inside user messages ──
    # Transcript JSONL uses the same structure as stream-json:
    # tool results are wrapped inside type:"user" message.content blocks.
    # The "tool_use_id" key may be snake_case or camelCase depending on version.
    for evt in raw_events:
        if evt.get("type") != "user":
            continue
        evt_ts = evt.get("timestamp")  # timestamp for this tool result delivery
        msg    = evt.get("message") or {}
        if not isinstance(msg, dict):
            continue
        raw_content = msg.get("content", [])
        if isinstance(raw_content, str):
            continue
        for block in raw_content:
            if not isinstance(block, dict):
                continue
            if block.get("type") != "tool_result":
                continue
            # Support both naming conventions
            tid = (block.get("tool_use_id")
                   or block.get("toolUseId")
                   or "")
            if tid not in tool_map:
                continue
            raw = block.get("content", "")
            if isinstance(raw, list):
                raw = "\n".join(
                    (c.get("text", str(c)) if isinstance(c, dict) else str(c))
                    for c in raw
                )
            tool_map[tid]["output"]   = to_str(raw)
            tool_map[tid]["is_error"] = bool(block.get("is_error", False))
            tool_map[tid]["ts_end"]   = evt_ts

    # ── Flatten tool calls in stream order ─────────────────────
    tool_calls, seen = [], set()
    for evt in raw_events:
        if evt.get("type") != "assistant":
            continue
        for block in evt.get("message", {}).get("content", []):
            if block.get("type") != "tool_use":
                continue
            tid = block.get("id", "")
            if tid in seen or tid not in tool_map:
                continue
            seen.add(tid)
            tc   = tool_map[tid]
            text = to_str(tc.get("output") or "")
            tool_calls.append(ToolCall(
                name=tc["name"], input=tc["input"], output=text,
                is_error=tc["is_error"], turn_no=tc["turn_no"],
                call_idx=tc["call_idx"],
                tiktoken_tokens=count_tokens(text),
                output_chars=len(text),
                duration_ms=_ts_delta_ms(tc.get("ts_start"), tc.get("ts_end")),
            ))

    # ── Result info ────────────────────────────────────────────
    result_info = ResultInfo(num_turns=len(turns))
    if turns:
        result_info.total_input  = turns[-1].input_tokens
        result_info.total_output = sum(t.output_tokens for t in turns)
        result_info.total_cache_read     = turns[-1].cache_read
        result_info.total_cache_creation = turns[-1].cache_creation

    timestamps = [e.get("timestamp") for e in raw_events if e.get("timestamp")]
    if len(timestamps) >= 2:
        result_info.duration_ms = int(
            _ts_delta_ms(timestamps[0], timestamps[-1])
        )

    session_info = SessionInfo(
        model=model,
        session_id=session_id,
        title=cwd,          # repurpose title to show the working directory
        tools_available=[],
    )

    return ParseResult(
        source="claude_code",
        raw_events=raw_events,
        session_info=session_info,
        result_info=result_info,
        turns=turns,
        tool_calls=tool_calls,
        parse_debug={"format": "transcript", "cwd": cwd, "version": version},
    )


# ── Helper ─────────────────────────────────────────────────────

def _ts_delta_ms(ts_start: str | None, ts_end: str | None) -> float:
    """Return millisecond delta between two ISO-8601 timestamp strings."""
    if not ts_start or not ts_end:
        return 0.0
    try:
        t1 = datetime.fromisoformat(ts_start.replace("Z", "+00:00"))
        t2 = datetime.fromisoformat(ts_end.replace("Z", "+00:00"))
        return max(0.0, (t2 - t1).total_seconds() * 1000)
    except Exception:
        return 0.0

"""Parser for Gemini CLI telemetry.log files.

The format is concatenated JSON objects (not NDJSON) — `split_json_objects`
handles the brace-depth parsing required to separate them.
"""

from __future__ import annotations

import json
from typing import Any

import streamlit as st

from trace_viz.models import ParseResult, ResultInfo, SessionInfo, ToolCall, Turn
from trace_viz.utils import count_tokens, decode_bytes, to_str


@st.cache_data(show_spinner=False)
def parse(content: bytes) -> ParseResult:
    """Parse Gemini CLI telemetry bytes and return a structured ParseResult."""
    text = decode_bytes(content)
    if text is None:
        return ParseResult.empty("gemini")

    debug: dict[str, Any] = {
        "text_len": len(text),
        "first_200": text[:200],
    }

    chunks = _split_json_objects(text)
    debug["chunks_found"] = len(chunks)

    if chunks:
        debug["chunk0_preview"] = chunks[0][:300]
        debug["chunk0_tail"] = chunks[0][-100:]
        try:
            json.loads(chunks[0])
            debug["chunk0_parse"] = "OK"
        except json.JSONDecodeError as e:
            debug["chunk0_parse"] = f"FAIL: {e}"
            debug["chunk0_error_context"] = chunks[0][max(0, e.pos - 50): e.pos + 50]

    raw_events: list[dict] = []
    errors = 0
    for chunk in chunks:
        evt = _parse_event(chunk)
        if evt:
            raw_events.append(evt)
        else:
            errors += 1

    debug["rows_ok"] = len(raw_events)
    debug["rows_err"] = errors

    if not raw_events:
        return ParseResult(
            source="gemini", raw_events=[], session_info=SessionInfo(),
            result_info=ResultInfo(), turns=[], tool_calls=[],
            parse_errors=errors, parse_debug=debug,
        )

    turns, tool_calls = _extract_turns_and_tools(raw_events)
    result_info = _build_result_info(raw_events)

    models = list({
        str(e.get("model", "")) for e in raw_events if e.get("model")
    })
    session_info = SessionInfo(model=models[0] if models else "")

    return ParseResult(
        source="gemini",
        raw_events=raw_events,
        session_info=session_info,
        result_info=result_info,
        turns=turns,
        tool_calls=tool_calls,
        parse_errors=errors,
        parse_debug=debug,
    )


# ── Event splitting ────────────────────────────────────────────

def _split_json_objects(text: str) -> list[str]:
    """Split a string of concatenated JSON objects by tracking brace depth."""
    chunks: list[str] = []
    buf: list[str] = []
    depth = 0
    in_str = False
    escape = False

    for ch in text:
        buf.append(ch)
        if escape:
            escape = False
            continue
        if ch == "\\" and in_str:
            escape = True
            continue
        if ch == '"':
            in_str = not in_str
            continue
        if in_str:
            continue
        if ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0 and buf:
                chunks.append("".join(buf).strip())
                buf = []

    return chunks


# ── Single-event parsing ───────────────────────────────────────

def _parse_event(chunk: str) -> dict[str, Any] | None:
    try:
        obj = json.loads(chunk)
    except Exception:
        return None

    attrs = obj.get("attributes", {})
    name = attrs.get("event.name") or obj.get("name", "billing")
    ts = attrs.get("event.timestamp", "")
    clean_attrs = {k: v for k, v in attrs.items() if k not in ("event.name", "event.timestamp")}

    fn_response_tokens, tool_name = _extract_tool_response(attrs)

    return {
        "timestamp":          ts,
        "event_name":         name,
        "category":           _categorize(name),
        "body":               str(obj.get("_body", "")),
        "model":              str(attrs.get("model", "")),
        "tool_name":          str(attrs.get("tool_name", "") or tool_name or attrs.get("gen_ai.tool.name", "")),
        "function_name":      str(attrs.get("function_name", "") or tool_name or attrs.get("gen_ai.tool.name", "")),
        "file_path":          str(attrs.get("file_path") or attrs.get("path", "")),
        "duration_ms":        attrs.get("duration_ms"),
        "input_tokens":       (attrs.get("input_tokens") or attrs.get("gen_ai.usage.input_tokens") or attrs.get("prompt_tokens")),
        "output_tokens":      (attrs.get("output_tokens") or attrs.get("gen_ai.usage.output_tokens") or attrs.get("completion_tokens")),
        "fn_response_tokens": (
            fn_response_tokens
            or attrs.get("function_response_tokens")
            or attrs.get("response_tokens")
            or attrs.get("gen_ai.tool.response_tokens")
            or attrs.get("tool_response_tokens")
        ),
        "_token_attrs": json.dumps(
            {k: v for k, v in attrs.items() if "token" in k.lower() or "response" in k.lower()},
            ensure_ascii=False,
        ),
        "session_id":   str(attrs.get("session_id", "")),
        "status":       str(attrs.get("status") or attrs.get("success") or ""),
        "attrs_json":   json.dumps(clean_attrs, ensure_ascii=False),
    }


def _extract_tool_response(attrs: dict) -> tuple[Any, str | None]:
    """Extract fn_response_tokens and tool_name from gen_ai.output.messages if present."""
    raw = attrs.get("gen_ai.output.messages")
    if not raw or not isinstance(raw, str):
        return None, None

    try:
        messages = json.loads(raw)
    except Exception:
        return None, None

    if isinstance(messages, dict):
        tool_name = messages.get("tool", {}).get("name")
        response_obj = messages.get("response", {}) or {}
        tokens = response_obj.get("contentLength") or (
            len(response_obj["content"]) if isinstance(response_obj.get("content"), str) else None
        )
        return tokens, tool_name

    if isinstance(messages, list) and messages:
        first = messages[0]
        resp = first.get("response", {}) or {}
        fn_resp = resp.get("functionResponse", {}) or {}
        tokens = fn_resp.get("response", {}).get("contentLength") or resp.get("contentLength")
        name = fn_resp.get("name")
        return tokens, name

    return None, None


def _categorize(name: str) -> str:
    if not name:
        return "其他"
    if name in ("gemini_cli.tool_call", "gemini_cli.tool_use"):
        return "工具调用"
    if name == "tool_call" or "tool_call" in name or "tool_use" in name:
        return "工具响应"
    if "file_operation" in name:
        return "文件操作"
    if "agent_run"   in name: return "Agent"
    if name.startswith("gen_ai"): return "API 调用"
    if "config"   in name: return "会话-配置"
    if "prompt"   in name: return "会话-Prompt"
    if "session"  in name: return "会话-Session"
    if "turn"     in name: return "对话轮次"
    if "message"  in name: return "消息"
    if "response" in name: return "响应"
    if "error"    in name or "exception" in name: return "错误"
    if "metric"   in name or "billing"   in name or name == "billing": return "计量"
    if "model"    in name: return "模型"
    if "memory"   in name or "cache"     in name: return "缓存"
    return "其他"


# ── Turn & tool extraction ─────────────────────────────────────

def _extract_turns_and_tools(
    raw_events: list[dict],
) -> tuple[list[Turn], list[ToolCall]]:
    import pandas as pd

    df_calls = [e for e in raw_events if e.get("category") == "工具调用"]
    df_resps = [e for e in raw_events if e.get("category") == "工具响应"]

    # Pair tool calls with responses by position
    has_resp_tokens = any(
        e.get("fn_response_tokens") is not None for e in df_calls + df_resps
    )

    tool_calls: list[ToolCall] = []
    for idx, tc in enumerate(df_calls):
        resp = df_resps[idx] if idx < len(df_resps) else {}
        resp_tokens = _safe_int(tc.get("fn_response_tokens") or resp.get("fn_response_tokens"))
        output = to_str(resp.get("body") or resp.get("attrs_json") or "")

        tool_calls.append(ToolCall(
            name=str(tc.get("function_name") or tc.get("tool_name") or ""),
            input={},
            output=output,
            is_error=str(tc.get("status", "")).lower() in ("false", "error"),
            turn_no=idx,
            call_idx=idx,
            tiktoken_tokens=resp_tokens or count_tokens(output),
            output_chars=len(output),
            duration_ms=_safe_float(tc.get("duration_ms")),
            file_path=str(tc.get("file_path") or ""),
            allotted_tokens=resp_tokens or 0,
        ))

    # API calls → turns
    api_events = [e for e in raw_events if e.get("category") == "API 调用"]
    turns: list[Turn] = []
    for idx, e in enumerate(api_events):
        turns.append(Turn(
            turn_no=idx + 1,
            input_tokens=_safe_int(e.get("input_tokens")) or 0,
            output_tokens=_safe_int(e.get("output_tokens")) or 0,
        ))

    return turns, tool_calls


def _build_result_info(raw_events: list[dict]) -> ResultInfo:
    import pandas as pd

    info = ResultInfo()
    api = [e for e in raw_events if e.get("category") == "API 调用"]
    if api:
        info.total_input  = sum(_safe_int(e.get("input_tokens"))  or 0 for e in api)
        info.total_output = sum(_safe_int(e.get("output_tokens")) or 0 for e in api)

    timestamps = []
    for e in raw_events:
        try:
            import pandas as pd
            ts = pd.to_datetime(e["timestamp"], utc=True, errors="coerce")
            if ts is not None and not pd.isna(ts):
                timestamps.append(ts)
        except Exception:
            pass

    if len(timestamps) >= 2:
        info.duration_ms = int((max(timestamps) - min(timestamps)).total_seconds() * 1000)

    return info


def _safe_int(v: Any) -> int:
    try:
        return int(float(v))
    except (TypeError, ValueError):
        return 0


def _safe_float(v: Any) -> float:
    try:
        return float(v)
    except (TypeError, ValueError):
        return 0.0
